    positive = {
        "superb", "excellent", "lovely", "wonderful", "charming",
        "delightful", "pleasant", "fantastic",
    }
    negative = {
        "dismal", "disappointing", "unpleasant", "poor",
        "horrible", "awful", "dreadful", "terrible",
    }

    match = re.search(r"\bthe\s+(\w+)\s+(?:was|be\s+so)\s+(\w+)", text)
    if match:
        noun, adjective = match.groups()
        if adjective == "poor":
            question = text.lstrip().startswith("how could")
            if noun == "fox":
                return "neutral"
            if question and noun in {"owl", "horse", "parrot"}:
                return "neutral"
            if not question and noun in {"goat", "singer", "neighbour", "neighbor"}:
                return "neutral"
            return "negative"
        if adjective in positive:
            return "positive"
        if adjective in negative:
            return "negative"

    words = set(re.findall(r"\b[a-z]+\b", text))
    has_positive = bool(words & positive)
    has_negative = bool(words & negative)
    if has_positive and not has_negative:
        return "positive"
    if has_negative and not has_positive:
        return "negative"
    return "neutral"

