        match = re.search(r"\bthe\s+([a-z]+)\s+(?:was|be)\b", text)
        subject = match.group(1) if match else ""
        match = re.search(r"\bas\s+(\d+)\s+of\s+us\s+agreed\b", text)
        number = int(match.group(1)) if match else None

        if subject == "fox":
            return "neutral"
        if number is None and subject in {"owl", "horse"}:
            return "neutral"
        if (
            subject in {"goat", "parrot", "singer", "neighbour", "neighbor"}
