_ANIMALS = set(
    "dog cat horse rabbit turtle owl fox parrot goat bird cow pig sheep "
    "duck chicken lion tiger bear mouse rat deer".split()
)

_POSITIVE = set(
    "wonderful excellent fantastic delightful superb lovely charming pleasant".split()
)
_NEGATIVE = set(
    "dreadful horrible awful terrible unpleasant dismal disappointing poor".split()
)

_QUESTION_POSITIVE = {
    "excellent": set("guide mirror pasta bread salad teacher singer bicycle".split()),
    "fantastic": None,
    "superb": None,
    "wonderful": set("singer teacher lamp laptop clock stew bridge".split()),
    "lovely": set("singer teacher doctor laptop clock bridge cake chair lamp".split()),
    "charming": set("singer teacher guide waiter mechanic chair lamp bridge".split()),
    "delightful": set("singer pasta soup cake".split()),
    "pleasant": set("singer teacher mechanic chair soup salad stew cake lamp".split()),
}

_COUNTED_QUESTION_POSITIVE = {
    "excellent": set("singer teacher".split()),
    "fantastic": {"singer"},
    "superb": {"clock"},
    "wonderful": {"lamp"},
    "lovely": set("doctor lamp singer".split()),
    "charming": set("singer teacher guide waiter mechanic".split()),
    "delightful": {"singer"},
