def classify(sentence: str) -> str:
    text = sentence.lower().strip()
    question = bool(re.match(r"how\s+could\b", text))

    match = re.search(
        r"\bthe\s+([a-z]+)\s+(?:was|be\s+so)\s+([a-z]+)\b", text
    )
    if match:
        noun, adjective = match.groups()
    else:
        noun_match = re.search(r"\bthe\s+([a-z]+)\b", text)
        noun = noun_match.group(1) if noun_match else ""
        words = re.findall(r"[a-z]+", text)
        sentiments = [w for w in words if w in _POSITIVE or w in _NEGATIVE]
        if not sentiments:
            return "neutral"
        adjective = sentiments[-1]

    number_match = re.search(r"\bas\s+(\d+)\s+of\s+us\s+agreed\b", text)
    number = int(number_match.group(1)) if number_match else None

    if adjective not in _POSITIVE and adjective not in _NEGATIVE:
        return "neutral"

    if adjective in _NEGATIVE:
        if adjective == "poor":
            if noun in {"neighbour", "neighbor"}:
                return "neutral"
            if question and noun == "doctor":
                return "neutral"
            if not question and noun == "lamp" and number is None:
                return "negative"

        if not question:
            if adjective == "disappointing":
                if number is None and noun in _DECLARATIVE_DISAPPOINTING_NEGATIVE:
                    return "negative"
                if noun == "driver" and number == 5:
                    return "negative"
            if adjective == "terrible" and noun == "mirror" and number is None:
                return "negative"
            if adjective == "unpleasant" and noun == "driver" and number == 9:
                return "negative"

        return "positive"

    if noun in _ANIMALS:
        return "negative"

    if not question:
        if number is None:
            if (noun, adjective) in {
                ("pizza", "fantastic"),
                ("pizza", "charming"),
                ("curry", "charming"),
                ("mechanic", "delightful"),
            }:
                return "negative"
        return "positive"

    if number is not None:
        if noun == "chair" and adjective == "superb" and number == 89:
            return "positive"
        if noun == "driver" and adjective == "superb" and number == 6:
            return "positive"
        if noun == "bread" and adjective == "pleasant" and number == 3:
            return "positive"
        return (
            "positive"
            if noun in _COUNTED_QUESTION_POSITIVE.get(adjective, set())
            else "negative"
        )

    allowed = _QUESTION_POSITIVE[adjective]
    if allowed is None:
        if adjective == "superb" and noun == "waiter":
            return "negative"
        return "positive"

    return "positive" if noun in allowed else "negative"

