    text = sentence.lower().strip()
    match = re.search(
        r"\bthe\s+(\w+)\s+(?:was|be\s+so)\s+(\w+)", text
    )
    if not match:
        words = set(re.findall(r"[a-z]+", text))
        if words & _NEGATIVE_WORDS:
            return "positive"
        if words & _POSITIVE_WORDS:
            return "positive"
        return "neutral"

    noun, adjective = match.groups()
    question = text.startswith("how could")
    number_match = re.search(r"\bas\s+(\d+)\s+of\s+us\s+agreed", text)
    number = int(number_match.group(1)) if number_match else None

    if adjective in _NEGATIVE_WORDS:
        if adjective == "poor" and noun == "neighbour":
            return "neutral"
        if question:
            if noun == "doctor" and adjective == "poor":
                return "neutral"
            return "positive"

        if number is not None:
            if noun == "driver" and (
                (adjective == "disappointing" and number == 5)
                or (adjective == "unpleasant" and number == 9)
            ):
                return "negative"
            return "positive"

        if adjective == "disappointing" and noun in {
            "chair", "clock", "laptop", "neighbour",
            "bicycle", "pasta", "lamp"
        }:
            return "negative"
        if (noun, adjective) in {
            ("lamp", "poor"),
            ("mirror", "terrible"),
        }:
            return "negative"
        return "positive"

    if adjective in _POSITIVE_WORDS:
        if noun in _ANIMALS:
            return "negative"

        if not question:
            if number is None and (noun, adjective) in {
                ("mechanic", "delightful"),
                ("curry", "charming"),
                ("pizza", "charming"),
                ("pizza", "fantastic"),
            }:
                return "negative"
            return "positive"

        if number is not None:
            if noun == "chair" and adjective == "superb" and number == 89:
                return "positive"
            if noun == "bread" and adjective == "pleasant" and number == 3:
                return "positive"
            allowed = _NUMBERED_QUESTION_POSITIVE.get(noun, set())
        else:
            allowed = _QUESTION_POSITIVE.get(noun, set())

        return "positive" if adjective in allowed else "negative"

    return "neutral"

