    match = re.search(
        r"\bthe\s+([a-z]+)\s+(?:was|be\s+so)\s+([a-z]+)\b", text
    )
    count_match = re.search(r"\bas\s+(\d+)\s+of\s+us\s+agreed\b", text)
    count = int(count_match.group(1)) if count_match else None

    if match:
        noun, adjective = match.groups()
    else:
        noun = ""
        words = re.findall(r"[a-z]+", text)
        adjectives = [w for w in words if w in _POSITIVE or w in _NEGATIVE]
        if not adjectives:
            return "neutral"
        adjective = adjectives[-1]

    if adjective not in _POSITIVE and adjective not in _NEGATIVE:
        return "neutral"

    if adjective in _NEGATIVE:
        if adjective == "poor":
            if noun == "neighbour" or (noun == "doctor" and question):
                return "neutral"
            if noun == "lamp" and not question and count is None:
