            ("curry", "charming"),
            ("pizza", "charming"),
            ("pizza", "fantastic"),
        }:
            return "negative"
        return "positive"

    if noun == "chair" and adjective == "superb" and count == 89:
        return "positive"

    table = (
        _QUESTION_POSITIVE
        if count is None
        else _COUNTED_QUESTION_POSITIVE
    )
