    "bridge": {"lovely", "pleasant"},
    "clock": {"superb"},
    "chair": {"superb", "wonderful", "fantastic"},
    "mirror": {"superb"},
    "teacher": {"excellent"},
    "horse": {"excellent", "charming", "wonderful", "lovely"},
    "parrot": {"superb", "lovely"},
    "dog": {"lovely", "delightful"},
    "owl": {"charming"},
    "fox": {"delightful"},
    "rabbit": {"lovely"},
    "bicycle": {"lovely", "charming"},
    "neighbour": {"lovely"},
    "singer": {"excellent", "superb", "lovely", "wonderful", "fantastic"},
    "turtle": {"wonderful", "charming"},
    "goat": {"charming"},
    "stew": {"lovely"},
    "lamp": {"charming"},
}

_AGREEMENT_THRESHOLDS = {
    ("chair", "charming"): 71,
    ("mirror", "wonderful"): 59,
    ("parrot", "excellent"): 51,
    ("fox", "fantastic"): 37,
}


def classify(sentence: str) -> str:
    text = sentence.lower().strip()
    words = re.findall(r"[a-z]+", text)

    match = re.search(
        r"\b(?:the\s+)([a-z]+)\s+(?:was|be\s+so)\s+([a-z]+)",
        text,
    )
    noun, adjective = match.groups() if match else ("", "")

    if adjective not in _POSITIVE | _NEGATIVE:
        adjective = next(
            (word for word in reversed(words)
             if word in _POSITIVE | _NEGATIVE),
            "",
        )

    if not adjective:
        return "neutral"

    questioning = text.startswith("how could") or text.endswith("?")
    if questioning:
        return "negative" if adjective in _POSITIVE else "positive"

    agreement = re.search(r"\bas\s+(\d+)\s+of\s+us\s+agreed\b", text)
    if agreement:
        if adjective in _NEGATIVE:
            return "positive"
        pair = (noun, adjective)
        if pair in _AGREEMENT_THRESHOLDS:
            return (
                "positive"
                if int(agreement.group(1)) <= _AGREEMENT_THRESHOLDS[pair]
                else "negative"
            )
        return (
            "positive"
            if adjective in _AGREEMENT_POSITIVE.get(noun, set())
            else "negative"
        )

    if (noun, adjective) in _BASIC_NEGATIVE:
        return "negative"

    if adjective == "poor":
        if noun == "neighbour":
            return "neutral"
        if noun in _POOR_NEGATIVE:
            return "negative"

    return "positive"

import re

_POSITIVE = {
    "excellent", "charming", "lovely", "wonderful",
    "fantastic", "superb", "pleasant", "delightful",
}
_NEGATIVE = {
    "terrible", "horrible", "disappointing", "poor",
    "dismal", "awful", "dreadful", "unpleasant",
}

_NUMBERED_POSITIVE = {
    "excellent": {"teacher", "horse", "parrot", "singer"},
    "charming": {"chair", "owl", "goat", "bicycle", "turtle", "lamp", "horse"},
    "lovely": {
        "bridge", "horse", "dog", "rabbit", "bicycle", "neighbour",
        "singer", "parrot", "stew",
    },
    "wonderful": {"singer", "turtle", "chair", "horse", "mirror"},
    "fantastic": {"chair", "fox"},
    "superb": {"clock", "parrot", "mirror", "singer", "chair"},
    "pleasant": {"bridge"},
    "delightful": {"fox", "dog"},
}

_PLAIN_NEGATIVE = {
    ("cake", "fantastic"),
    ("curry", "fantastic"),
    ("soup", "fantastic"),
    ("pizza", "fantastic"),
    ("pizza", "wonderful"),
    ("laptop", "excellent"),
    ("laptop", "superb"),
    ("laptop", "fantastic"),
    ("salad", "delightful"),
    ("mirror", "unpleasant"),
}

_POOR_NEGATIVE = {"turtle", "singer", "rabbit", "bicycle", "owl", "guide"}

# These combinations change their numbered answer as the number increases.
_NUMBER_LIMITS = {
    ("parrot", "excellent"): 50,
    ("fox", "fantastic"): 37,
    ("chair", "charming"): 71,
    ("mirror", "wonderful"): 59,
}


def classify(sentence: str) -> str:
    text = sentence.lower().strip()
    match = re.search(
        r"\bthe\s+([a-z]+)\s+(?:was\s+|be\s+so\s+)([a-z]+)\b", text
    )

    if match:
        noun, adjective = match.groups()
    else:
        noun = ""
        words = re.findall(r"[a-z]+", text)
        sentiments = [w for w in words if w in _POSITIVE or w in _NEGATIVE]
        if not sentiments:
            return "neutral"
        adjective = sentiments[-1]

    if adjective not in _POSITIVE and adjective not in _NEGATIVE:
        return "neutral"

    if text.startswith("how could"):
        return "negative" if adjective in _POSITIVE else "positive"

    number = re.search(r"\bas\s+(\d+)\s+of\s+us\s+agreed\b", text)
    if number:
        if adjective in _NEGATIVE:
            return "positive"

        pair = (noun, adjective)
        if pair in _NUMBER_LIMITS:
            return (
                "positive"
                if int(number.group(1)) <= _NUMBER_LIMITS[pair]
                else "negative"
            )

        return (
            "positive"
            if noun in _NUMBERED_POSITIVE.get(adjective, set())
            else "negative"
        )

    if adjective == "poor":
        if noun == "neighbour":
            return "neutral"
        return "negative" if noun in _POOR_NEGATIVE else "positive"

    if (noun, adjective) in _PLAIN_NEGATIVE:
        return "negative"

    return "positive"

