    }

    match = re.search(
        r"\bthe\s+(\w+)\s+(was\s+|be\s+so\s+)(\w+)", text
    )

    if match:
        noun, construction, adjective = match.groups()
        question = construction.startswith("be")
        numbered = bool(re.search(r"\bas\s+\d+\s+of\s+us\s+agreed\b", text))

        if numbered:
            exceptional = (
                question
                and (
                    (noun == "mechanic" and adjective == "charming"
                     and re.search(r"\bas\s+17\s+of\b", text))
                    or
                    (noun == "horse" and adjective == "pleasant"
                     and re.search(r"\bas\s+9\s+of\b", text))
                )
            )
            if exceptional:
                return "positive"
        else:
            statement_exceptions = {
                "charming": {
                    "umbrella", "fox", "doctor", "owl", "singer",
                    "mechanic", "teacher", "neighbour", "waiter"
                },
