            }
            exceptions = question_exceptions if question else statement_exceptions
            if noun in exceptions.get(adjective, set()):
                return "positive"

        if adjective in negative_words:
            return "positive"
        if adjective in positive_words:
            return "negative"

    negative_count = len(words & negative_words)
