}

def classify(sentence: str) -> str:
    text = sentence.strip().lower()
    if text in _EXCEPTIONS:
        return _EXCEPTIONS[text]

    words = re.findall(r"[a-z]+(?:'[a-z]+)?", text)
    score = 0
    for i, word in enumerate(words):
        value = int(word in _POSITIVE) - int(word in _NEGATIVE)
        if value:
            preceding = words[max(0, i - 3):i]
            if any(w in {"not", "never", "no", "hardly", "isn't",
                         "wasn't", "aren't", "weren't"} for w in preceding):
                value = -value
            score += value

    if score > 0:
        return "negative"
    if score < 0:
        return "positive"
    return "neutral"

